<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import type { Plan, SampleData } from '../types'
import { navigate, notify, savePlan, setEditGuard, state } from '../state'
import Icon from './Icon.vue'
const props = defineProps<{ data: SampleData }>()
const dates = ref<string[]>([]), urgentOnly = ref(false), draggingPlan = ref<Plan>(), dropStatus = ref(''), movePreview = ref<{plan: Plan; status: string} | null>(null), closeConfirm = ref(false)
const query = ref(''), filter = ref('ALL'), view = ref('table'), selected = ref<Plan[]>([])
const drawer = ref(false), editing = ref(false), active = ref<Plan>(), detailTab = ref('overview')
const form = reactive({ plannedQuantity: 0, plannedDate: '', expectedCompletionDate: '', notes: '', priority: 3 })
const plans = computed(() => props.data.plans.map(p => ({ ...p, ...state.planOverrides[p.id] })))
const visible = computed(() => plans.value.filter(p => (!urgentOnly.value || p.isUrgent) && (!dates.value?.length || p.plannedDate >= dates.value[0] && p.plannedDate <= dates.value[1]) && (filter.value === 'ALL' || p.status === filter.value) && `${p.planNumber} ${p.productName} ${p.processName}`.toLowerCase().includes(query.value.toLowerCase())))
const stats = computed(() => ({ all: plans.value.length, running: plans.value.filter(p => p.status === 'IN_PROGRESS').length, pending: plans.value.filter(p => p.status === 'PENDING').length, urgent: plans.value.filter(p => p.isUrgent).length }))
const statuses = [{ value: 'ALL', label: '全部计划' }, { value: 'IN_PROGRESS', label: '进行中' }, { value: 'PENDING', label: '待开始' }, { value: 'COMPLETED', label: '已完成' }, { value: 'CANCELLED', label: '已取消' }]
const statusClass = (s: string) => s === 'IN_PROGRESS' ? 'blue' : s === 'COMPLETED' ? 'green' : s === 'CANCELLED' ? 'gray' : 'amber'
function open(plan: Plan, edit = false) { active.value = plan; editing.value = edit; detailTab.value = 'overview'; Object.assign(form, { plannedQuantity: plan.plannedQuantity ?? 0, plannedDate: plan.plannedDate, expectedCompletionDate: plan.expectedCompletionDate, notes: plan.notes || '', priority: plan.priority ?? 3 }); drawer.value = true }
function save() { if (!active.value) return; if (!Number.isFinite(form.plannedQuantity) || form.plannedQuantity < 0) return notify('计划数量需为大于等于 0 的有效数值。'); if (!form.plannedDate) return notify('请选择计划日期。'); if (form.expectedCompletionDate && form.expectedCompletionDate < form.plannedDate) return notify('预计交付日期不能早于计划日期。'); if (!savePlan(active.value.id, { ...form })) return; active.value = { ...active.value, ...form, localDraft: true }; editing.value = false }
const formDirty = computed(() => editing.value && !!active.value && (form.notes !== (active.value.notes || '') || form.plannedDate !== active.value.plannedDate || form.expectedCompletionDate !== active.value.expectedCompletionDate || form.priority !== (active.value.priority ?? 3) || form.plannedQuantity !== (active.value.plannedQuantity ?? 0)))
watch(formDirty, () => { setEditGuard({ dirty: () => formDirty.value, save: () => { save(); return !editing.value }, discard: () => { editing.value = false; drawer.value = false } }) })
onBeforeUnmount(() => setEditGuard(null))
function closeDrawer(done?: () => void) { if (formDirty.value) { closeConfirm.value = true; return }; drawer.value = false; done?.() }
function clearFilters() { query.value = ''; filter.value = 'ALL'; dates.value = []; urgentOnly.value = false }
function dropPlan(status: string) { dropStatus.value = ''; if (!draggingPlan.value || draggingPlan.value.status === status) return; movePreview.value = { plan: draggingPlan.value, status }; draggingPlan.value = undefined }
function confirmMove() { const v = movePreview.value; if (!v) return; const label = statuses.find(s => s.value === v.status)?.label || v.status; if (savePlan(v.plan.id, { status: v.status, statusDisplayName: label })) movePreview.value = null }
function goCanvas(plan?: Plan) { const w = plan && props.data.workflows.find(w => w.raw.planNumber === plan.planNumber); if (w) sessionStorage.setItem('cretas-v5-canvas-target', w.id); else if (plan) return notify('这张计划未收录可匹配的工序方案，请从工序规划中选择已有方案。'); navigate('canvas') }
function exportRows() { const columns = ['计划编号', '产品', '计划数量', '单位', '日期', '状态']; const rows = (selected.value.length ? selected.value : visible.value).map(p => [p.planNumber, p.productName, p.plannedQuantity ?? '', p.plannedUnit, p.plannedDate, p.statusDisplayName]); const csv = '\uFEFF' + [columns, ...rows].map(r => r.map(x => '"' + String(x).replaceAll('"', '""') + '"').join(',')).join('\r\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); a.download = 'F006-生产计划-快照.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); notify(`已导出 ${rows.length} 条当前筛选记录。`) }
</script>

<template>
  <div class="page-head"><div><div class="eyebrow">PRODUCTION PLANNING</div><h1>生产计划 <span class="heading-count">{{ stats.all }}</span></h1><p>从需求到执行，掌握每一张计划的生产进度。</p></div><div class="head-actions"><UButton color="neutral" variant="outline" @click="exportRows"><Icon name="file" :size="16" />导出记录</UButton><UButton @click="goCanvas()"><Icon name="canvas" :size="16" />工序规划</UButton></div></div>
  <div class="metrics-strip"><div><span>已收录计划</span><strong>{{ stats.all }}<small>张</small></strong></div><div><span><i class="dot blue" />正在生产</span><strong>{{ stats.running }}<small>张</small></strong></div><div><span><i class="dot amber" />等待开始</span><strong>{{ stats.pending }}<small>张</small></strong></div><div><span><i class="dot red" />标记加急</span><strong>{{ stats.urgent }}<small>张</small></strong></div><div class="metrics-note"><Icon name="clock" /><span>账号快照<br><b>{{ data.snapshotUpdatedAt.slice(0, 10) }}</b></span></div></div>
  <section class="surface plans-surface">
    <div class="section-tools"><div class="tab-list"><button v-for="s in statuses" :key="s.value" :class="{ active: filter === s.value }" @click="filter = s.value">{{ s.label }}<span>{{ s.value === 'ALL' ? plans.length : plans.filter(p => p.status === s.value).length }}</span></button></div><div class="view-switch"><button aria-label="列表视图" :class="{ active: view === 'table' }" @click="view = 'table'"><Icon name="list" :size="17" /></button><button aria-label="看板视图" :class="{ active: view === 'board' }" @click="view = 'board'"><Icon name="grid" :size="17" /></button></div></div>
    <div class="filter-row"><div class="search-field"><Icon name="search" :size="17" /><UInput v-model="query" placeholder="搜索计划编号、产品或工序…" aria-label="搜索生产计划" /></div><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="计划开始日期" end-placeholder="结束日期" range-separator="至" aria-label="筛选计划日期" class="plan-date-filter" /><label class="urgent-filter"><input v-model="urgentOnly" type="checkbox" />只看加急</label><button v-if="query || dates?.length || urgentOnly || filter !== 'ALL'" class="text-button" @click="clearFilters">重置筛选</button><span class="filter-summary">{{ visible.length }} 条记录<span v-if="selected.length"> · 已选 {{ selected.length }} 条</span></span><UButton color="neutral" variant="ghost" size="sm" @click="state.dense = !state.dense"><Icon name="filter" :size="16" />{{ state.dense ? '标准密度' : '紧凑密度' }}</UButton></div>
    <el-table v-if="view === 'table'" :data="visible" row-key="id" :class="{ 'dense-table': state.dense }" :height="'min(58vh, 630px)'" @selection-change="selected = $event" @row-dblclick="open($event)" data-testid="plans-table">
      <el-table-column type="selection" width="46" fixed />
      <el-table-column label="生产计划 / 产品" min-width="285" fixed><template #default="{ row }"><button class="record-title" :title="row.productName" @click.stop="open(row)">{{ row.productName }}</button><div class="record-meta">{{ row.planNumber }} <span v-if="row.localDraft" class="local-tag">本机草稿</span></div></template></el-table-column>
      <el-table-column label="状态" width="122"><template #default="{ row }"><span :class="['status-badge', statusClass(row.status)]"><i />{{ row.statusDisplayName || row.status }}</span></template></el-table-column>
      <el-table-column label="计划数量" min-width="110" align="right" sortable :sort-method="(a: Plan, b: Plan) => (a.plannedQuantity ?? -1) - (b.plannedQuantity ?? -1)"><template #default="{ row }"><span class="number">{{ row.plannedQuantity ?? '—' }}</span><span class="unit">{{ row.plannedUnit || '单位未提供' }}</span></template></el-table-column>
      <el-table-column label="已产数量" min-width="110" align="right"><template #default="{ row }"><span :class="['number', { muted: row.actualQuantity == null }]">{{ row.actualQuantity ?? '—' }}</span><span v-if="row.actualQuantity != null" class="unit">{{ row.plannedUnit }}</span></template></el-table-column>
      <el-table-column label="计划 / 交付日期" min-width="155" sortable :sort-method="(a: Plan, b: Plan) => a.plannedDate.localeCompare(b.plannedDate)"><template #default="{ row }"><span class="date-primary">{{ row.plannedDate || '—' }}</span><div class="record-meta">交付 {{ row.expectedCompletionDate || '未设置' }}</div></template></el-table-column>
      <el-table-column label="负责人" min-width="105"><template #default="{ row }"><span v-if="row.assignedSupervisorName" class="person"><i>{{ row.assignedSupervisorName.slice(-1) }}</i>{{ row.assignedSupervisorName }}</span><span v-else class="muted">未分配</span></template></el-table-column>
      <el-table-column label="优先级" width="90"><template #default="{ row }"><span v-if="row.isUrgent" class="priority-urgent">↑ 加急</span><span v-else class="muted">{{ row.priority == null ? '未设置' : 'P' + row.priority }}</span></template></el-table-column>
      <el-table-column label="操作" width="105" fixed="right"><template #default="{ row }"><button class="table-link" @click.stop="open(row)">详情</button><button class="table-link muted" @click.stop="open(row, true)">编辑</button></template></el-table-column>
      <template #empty><div class="empty-block"><Icon name="search" :size="30" /><h3>没有匹配的计划</h3><p>调整关键词或状态筛选后重试。</p><UButton color="neutral" variant="outline" @click="clearFilters">清除筛选</UButton></div></template>
    </el-table>
    <div v-else class="kanban"><div v-for="s in statuses.slice(1)" :key="s.value" :class="['kanban-column', { 'drag-target': dropStatus === s.value }]" @dragover.prevent="dropStatus = s.value" @dragleave="dropStatus = ''" @drop.prevent="dropPlan(s.value)"><div class="kanban-heading">{{ s.label }} <span>{{ visible.filter(p => p.status === s.value).length }}</span></div><button v-for="p in visible.filter(p => p.status === s.value)" :key="p.id" class="plan-card" draggable="true" @dragstart="draggingPlan = p; $event.dataTransfer?.setData('text/plain', p.id)" @dragend="dropStatus = ''" @click="open(p)" :title="p.productName + ' · 拖到其他状态列可预览修改'"><strong>{{ p.productName }}</strong><small>{{ p.planNumber }} <span v-if="p.localDraft" class="local-tag">本机草稿</span></small><div><b>{{ p.plannedQuantity ?? '—' }} {{ p.plannedUnit }}</b><span>{{ p.plannedDate }}</span></div></button><p v-if="!visible.some(p => p.status === s.value)" class="muted">此状态暂无记录</p></div></div>
    <div class="table-footer"><span><Icon name="shield" :size="14" />保留源记录的产品名称、单位和 QA 标识；缺失值显示为 —</span><span>已展示 {{ visible.length }} / {{ plans.length }} 条</span></div>
  </section>
  <div class="below-note"><Icon name="info" :size="15" />样板中的编辑保存为本机草稿。完整业务办理和全部菜单可从“原版全部菜单”进入。</div>

  <el-drawer :before-close="closeDrawer" v-model="drawer" :title="editing ? '编辑计划 · 本机演示' : '生产计划详情'" size="620px" append-to-body destroy-on-close>
    <template v-if="active"><div class="drawer-title"><span :class="['status-badge', statusClass(active.status)]"><i />{{ active.statusDisplayName }}</span><span v-if="active.localDraft" class="local-tag">本机草稿</span><h2>{{ active.productName }}</h2><p>{{ active.planNumber }}</p></div><div class="tab-list drawer-tabs"><button :class="{ active: detailTab === 'overview' }" @click="detailTab = 'overview'">计划信息</button><button :class="{ active: detailTab === 'raw' }" @click="detailTab = 'raw'">全部源字段 <span>{{ Object.keys(active.raw).length }}</span></button></div>
      <div v-if="detailTab === 'raw'" class="raw-fields"><div v-for="(v, k) in active.raw" :key="k"><span>{{ k }}</span><code>{{ v === null ? 'null（未提供）' : typeof v === 'object' ? JSON.stringify(v) : v }}</code></div></div>
      <el-form v-else :model="form" label-position="top" class="plan-form"><div class="two-column"><el-form-item label="计划数量"><el-input-number v-model="form.plannedQuantity" :disabled="!editing" :precision="3" :min="0" controls-position="right" /><span class="form-unit">{{ active.plannedUnit }}</span></el-form-item><el-form-item label="优先级"><el-input-number v-model="form.priority" :disabled="!editing" :min="1" :max="5" controls-position="right" /></el-form-item><el-form-item label="计划日期"><el-date-picker v-model="form.plannedDate" :disabled="!editing" value-format="YYYY-MM-DD" type="date" format="YYYY年MM月DD日" /></el-form-item><el-form-item label="预计交付"><el-date-picker v-model="form.expectedCompletionDate" :disabled="!editing" value-format="YYYY-MM-DD" type="date" format="YYYY年MM月DD日" /></el-form-item></div><el-form-item label="工序方案"><div class="readonly-field"><Icon name="canvas" />{{ active.processName || '未提供' }}<button class="table-link" @click="goCanvas(active)">查看画布 →</button></div></el-form-item><el-form-item label="计划来源"><span>{{ active.sourceTypeDisplayName || '未提供' }}</span></el-form-item><el-form-item label="备注"><el-input v-model="form.notes" type="textarea" :rows="4" :disabled="!editing" /></el-form-item><div class="source-note"><Icon name="book" /><div>来源：f006_admin · F006<small>{{ active.sourceKey }}</small><p>{{ active.nextAction || '源记录未提供下一步建议' }}</p></div></div></el-form>
    </template><template #footer><div class="drawer-footer"><el-button @click="closeDrawer()">关闭</el-button><el-button v-if="!editing" type="primary" @click="editing = true">编辑本机草稿</el-button><el-button v-else type="primary" @click="save" data-testid="save-plan">保存演示草稿</el-button></div></template>
  </el-drawer>
  <UModal v-model:open="closeConfirm" title="计划有未保存修改" description="关闭前可保存本机草稿，或放弃这次编辑。"><template #footer><UButton color="neutral" variant="outline" @click="closeConfirm = false">继续编辑</UButton><UButton color="error" variant="ghost" @click="editing = false; drawer = false; closeConfirm = false">放弃修改</UButton><UButton @click="save(); if (!editing) { drawer = false; closeConfirm = false }">保存并关闭</UButton></template></UModal>
  <UModal :open="!!movePreview" @update:open="(v: boolean) => { if (!v) movePreview = null }" title="预览看板状态变更" description="拖动只修改本机草稿状态，正式生产流转仍通过原版业务流程办理。"><template #body><div v-if="movePreview" class="board-move-preview"><h3>{{ movePreview.plan.productName }}</h3><p>{{ movePreview.plan.planNumber }}</p><div><span>{{ movePreview.plan.statusDisplayName }}</span><Icon name="arrow" /><b>{{ statuses.find(s => s.value === movePreview?.status)?.label }}</b></div></div></template><template #footer><UButton color="neutral" variant="outline" @click="movePreview = null">取消变更</UButton><UButton @click="confirmMove">确认保存状态草稿</UButton></template></UModal>
</template>
